{"content":"'use server'

import { updateTag } from 'next/cache'
import { createPostRecord } from '@/lib/data'

export type CreatePostState = {
  error?: string
  success?: boolean
}

export async function createPost(
  _prevState: CreatePostState,
  formData: FormData,
): Promise<CreatePostState> {
  const title = (formData.get('title') as string | null)?.trim()
  const content = (formData.get('content') as string | null)?.trim()

  if (!title) {
    return { error: 'Title is required.' }
  }
  if (!content) {
    return { error: 'Content is required.' }
  }

  await createPostRecord(title, content)

  // Immediately expire the "posts" cache. Unlike revalidateTag (which serves
  // stale content while fresh data loads in the background), updateTag
  // guarantees the next request waits for fresh data — so the user never sees
  // the stale cached list after creating a post.
  await updateTag('posts')

  return { success: true }
}
